"""SQLite transactions retain every bounded submission, including invalid JSON."""

import json
import secrets
import sqlite3
from contextlib import contextmanager
from pathlib import Path


class Store:
    def __init__(self, path: Path):
        self.path = path
        path.parent.mkdir(parents=True, exist_ok=True)
        with self.connection() as db:
            db.executescript("""
                PRAGMA journal_mode=WAL;
                CREATE TABLE IF NOT EXISTS challenges (
                    id TEXT PRIMARY KEY, title TEXT NOT NULL, date TEXT NOT NULL,
                    puzzle_version TEXT NOT NULL, opens_at TEXT, closes_at TEXT,
                    closed INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL
                );
                CREATE TABLE IF NOT EXISTS attempts (
                    id TEXT PRIMARY KEY, challenge_id TEXT NOT NULL,
                    roll_number TEXT NOT NULL, received_at TEXT NOT NULL,
                    token_hash TEXT NOT NULL, raw BLOB NOT NULL, report TEXT NOT NULL,
                    eligible INTEGER NOT NULL, eligibility_reason TEXT NOT NULL,
                    FOREIGN KEY(challenge_id) REFERENCES challenges(id)
                );
                CREATE INDEX IF NOT EXISTS attempts_challenge ON attempts(challenge_id);
                CREATE INDEX IF NOT EXISTS attempts_roll ON attempts(roll_number);
            """)

    @contextmanager
    def connection(self):
        db = sqlite3.connect(self.path, timeout=15)
        db.row_factory = sqlite3.Row
        db.execute("PRAGMA foreign_keys=ON")
        try:
            with db:
                yield db
        finally:
            db.close()

    def challenges(self):
        with self.connection() as db:
            return [dict(row) for row in db.execute("SELECT * FROM challenges ORDER BY created_at")]

    def challenge(self, identity: str):
        with self.connection() as db:
            row = db.execute("SELECT * FROM challenges WHERE id=?", (identity,)).fetchone()
            return dict(row) if row else None

    def create_challenge(self, values: dict):
        identity = secrets.token_hex(12)
        with self.connection() as db:
            db.execute(
                """INSERT INTO challenges
                (id,title,date,puzzle_version,opens_at,closes_at,created_at)
                VALUES (?,?,?,?,?,?,?)""",
                (
                    identity,
                    values["title"],
                    values["date"],
                    values["puzzle_version"],
                    values["opens_at"],
                    values["closes_at"],
                    values["created_at"],
                ),
            )
        return self.challenge(identity)

    def close_challenge(self, identity: str):
        with self.connection() as db:
            db.execute("UPDATE challenges SET closed=1 WHERE id=?", (identity,))

    def save_attempt(self, values: dict) -> None:
        with self.connection() as db:
            db.execute(
                """INSERT INTO attempts
                (id,challenge_id,roll_number,received_at,token_hash,raw,report,eligible,eligibility_reason)
                VALUES (?,?,?,?,?,?,?,?,?)""",
                (
                    values["id"],
                    values["challenge_id"],
                    values["roll_number"],
                    values["received_at"],
                    values["token_hash"],
                    values["raw"],
                    json.dumps(values["report"]),
                    values["eligible"],
                    values["eligibility_reason"],
                ),
            )

    def attempt(self, identity: str):
        with self.connection() as db:
            row = db.execute("SELECT * FROM attempts WHERE id=?", (identity,)).fetchone()
            return dict(row) if row else None

    def attempts(self, challenge_id: str | None = None, roll_number: str | None = None):
        query = (
            "SELECT id,challenge_id,roll_number,received_at,report,eligible,eligibility_reason "
            "FROM attempts"
        )
        where, parameters = [], []
        for column, value in (("challenge_id", challenge_id), ("roll_number", roll_number)):
            if value:
                where.append(column + "=?")
                parameters.append(value)
        if where:
            query += " WHERE " + " AND ".join(where)
        query += " ORDER BY received_at DESC"
        with self.connection() as db:
            return [dict(row) for row in db.execute(query, parameters)]
